# frequency in data
txt=[]
for f in glob.glob('../apk/app/www/data/ep/*.json'):
  d=json.load(open(f))
  for g in d['groups'].values():
    for it in g:
      if it[0]=='S': txt.append(it[1]+'\n'+it[2])
      elif it[0]=='N': txt.append(it[1])
      elif it[0]=='T': txt.append(it[2])
blob='\n'.join(txt)
seen=set(); rows=[]
for ja,ko,cat,src,note in G:
  if ja in seen: continue
  seen.add(ja); rows.append((ja,ko,cat,src,note,blob.count(ja)))
with open('ls_glossary.csv','w',encoding='utf-8-sig',newline='') as f:
  w=csv.writer(f); w.writerow(['일본어','한국어','분류','근거','메모','등장 횟수'])
  for r in rows: w.writerow(r)
json.dump({ja:ko for ja,ko,*_ in rows},open('ls_glossary.json','w'),ensure_ascii=False,indent=1)
c=collections.Counter((r[2],r[3]) for r in rows); print(len(rows),c)
print('unused',[r[0] for r in rows if r[5]==0])
